import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("A vendor from another tenant is not found", { tag: "@VEN-07" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor that belongs to another tenant, "Globex Procurement"
  const member = await apiAs("member");
  const otherVendor = await factory.vendor({ as: "otherTenant", name: uniqueName("Globex Vendor") });

  // Act: the Northwind member requests that vendor by id
  const response = await member.get(`/api/vendors/${otherVendor.id}`);

  // Assert
  const body = await expectStatus(response, 404);
  expect(body.error.code).toBe("vendor_not_found");
});
